// Idempotence alone: dedupes retries within ONE producer session + ONE partition
enable.idempotence=true

// Transactions: atomic multi-partition writes + atomic offset commit
producer.initTransactions();
producer.beginTransaction();
producer.send(new ProducerRecord<>("orders-enriched", key, value));
producer.sendOffsetsToTransaction(consumerOffsets, consumerGroupMetadata);
producer.commitTransaction(); // all-or-nothing across topic + offsets

// What this does NOT cover: the external sink write below still needs
// its own idempotency (e.g. an upsert keyed by topic-partition-offset)
// because a crash between the DB write and the offset commit will
// replay this record into Postgres a second time.
db.upsert("orders", record, key = topicPartitionOffsetKey);

