# modules/fabric-eventhub/variables.tf
variable "environment" {
  type        = string
  description = "Short environment name, e.g. dev or prod"
}

variable "location" {
  type    = string
  default = "eastus2"
}

variable "resource_group_name" {
  type = string
}

variable "fabric_capacity_sku" {
  type        = string
  description = "Fabric capacity SKU, e.g. F2, F64"
}

variable "fabric_admin_members" {
  type = list(string)
}

variable "eventhub_namespace_sku" {
  type    = string
  default = "Standard"
}

variable "eventhub_throughput_units" {
  type    = number
  default = 1
}

# modules/fabric-eventhub/main.tf
resource "azurerm_fabric_capacity" "this" {
  name                = "fab-${var.environment}-cap"
  resource_group_name = var.resource_group_name
  location            = var.location

  sku {
    name = var.fabric_capacity_sku
    tier = "Fabric"
  }

  administration_members = var.fabric_admin_members
}

resource "azurerm_eventhub_namespace" "this" {
  name                = "evhns-${var.environment}-afde"
  resource_group_name = var.resource_group_name
  location            = var.location
  sku                 = var.eventhub_namespace_sku
  capacity            = var.eventhub_throughput_units
}

# modules/fabric-eventhub/outputs.tf
output "fabric_capacity_id" {
  value = azurerm_fabric_capacity.this.id
}

output "eventhub_namespace_connection_string" {
  value     = azurerm_eventhub_namespace.this.default_primary_connection_string
  sensitive = true
}

# root main.tf -- called twice, zero duplicated resource logic
module "dev" {
  source                    = "./modules/fabric-eventhub"
  environment               = "dev"
  resource_group_name       = azurerm_resource_group.dev.name
  fabric_capacity_sku       = "F2"
  fabric_admin_members      = ["dev-admins@contoso.com"]
  eventhub_throughput_units = 1
}

module "prod" {
  source                    = "./modules/fabric-eventhub"
  environment               = "prod"
  resource_group_name       = azurerm_resource_group.prod.name
  fabric_capacity_sku       = "F64"
  fabric_admin_members      = ["prod-admins@contoso.com"]
  eventhub_throughput_units = 4
}

